def _native_platform_key():
    machine = _platform.machine().lower()
    arch = {'arm64': 'aarch64', 'aarch64': 'aarch64',
             'x86_64': 'x86_64', 'amd64': 'x86_64'}.get(machine)
    if arch is None:
        return None
    if sys.platform == 'darwin':
        return 'aarch64-macos' if arch == 'aarch64' else None
    if sys.platform.startswith('linux'):
        return arch + '-linux'
    if sys.platform == 'win32':
        return 'x86_64-windows' if arch == 'x86_64' else None
    return None


_native_library_cache = {}
_native_keep_open = []  # memfd handles that must outlive the CDLL load


def _load_native_library():
    key = _native_platform_key()
    if key is None or key not in _NATIVE_LIBS:
        return None
    if key in _native_library_cache:
        return _native_library_cache[key]
    info = _NATIVE_LIBS[key]
    raw = None

    def _verified_bytes():
        data = lzma.decompress(base64.b85decode(''.join(info['data'].split())))
        if (hashlib.sha256(data).hexdigest() != info['sha256']
                or len(data) != info['size']):
            return None
        return data

    try:
        lib = None
        if sys.platform.startswith('linux'):
            # memfd + dlopen: the library never touches the filesystem.
            try:
                blob = _verified_bytes()
                if blob is not None:
                    fd = os.memfd_create('vcdidx', 0)
                    os.write(fd, blob)
                    os.lseek(fd, 0, os.SEEK_SET)
                    lib = ctypes.CDLL('/proc/self/fd/{}'.format(fd))
                    _native_keep_open.append(fd)  # mapping lives with the fd
            except (AttributeError, OSError, ValueError):
                lib = None  # fall through to the disk path
        if lib is None:
            if sys.platform == 'win32':
                base = os.environ.get('LOCALAPPDATA') or os.path.expanduser('~')
                cache_dir = os.path.join(base, 'vcd_analyzer-native')
            else:
                cache_dir = os.path.join(os.path.expanduser('~'), '.cache',
                                         'vcd_analyzer-native')
            target = os.path.join(cache_dir, 'vcdidx-{}-{}{}'.format(
                _NATIVE_ABI_VERSION, info['sha256'][:16], info['ext']))
            if not os.path.exists(target):
                raw = _verified_bytes()
                if raw is None:
                    return None
                os.makedirs(cache_dir, exist_ok=True, mode=0o700)
                fd, tmp = tempfile.mkstemp(dir=cache_dir, suffix='.part')
                try:
                    with os.fdopen(fd, 'wb') as out:
                        out.write(raw)
                    os.replace(tmp, target)
                except BaseException:
                    try:
                        os.unlink(tmp)
                    except OSError:
                        pass
                    raise
            else:
                # Re-verify a pre-existing cache file before loading it:
                # the extraction path checks, the cached path must too.
                with open(target, 'rb') as f:
                    if hashlib.sha256(f.read()).hexdigest() != info['sha256']:
                        return None
            lib = ctypes.CDLL(target)
        if lib.vcdidx_abi_version() != _NATIVE_ABI_VERSION:
            return None
        lib.vcdidx_abi_build.restype = ctypes.c_int
        lib.vcdidx_abi_build.argtypes = [
            ctypes.c_char_p, ctypes.c_size_t, ctypes.c_char_p, ctypes.c_char_p,
            ctypes.c_char_p, ctypes.c_size_t, ctypes.c_char_p, ctypes.c_size_t]
        _native_library_cache[key] = lib
        return lib
    except (OSError, ValueError, AttributeError, ImportError):
        return None


def _NATIVE_INDEX_BUILD(path, sidecar, block_bytes, budget_bytes=0, max_block_bytes=0,
                        threads=0, parallel_min=NATIVE_PARALLEL_MIN):
    """Build the sidecar natively. None when no usable library (the caller
    falls back to the pure-Python builder); ValueError for fatal build
    errors (non-monotonic timestamps, changed source) so they surface
    instead of being rebuilt slowly and reported late."""
    lib = _load_native_library()
    if lib is None:
        return None
    started = time.perf_counter()
    parser = VCDParser(str(path))
    symbols = raw_symbols(parser)
    start = data_start(path)
    manifest = ('data_start {}\nblock_bytes {}\nbudget_bytes {}\nmax_block_bytes {}\n'
                'max_token_len {}\nthreads {}\nparallel_min {}\nsymbols {}\n{}\n').format(
        start, block_bytes, budget_bytes, max_block_bytes, MAX_DATA_TOKEN_LEN,
        threads, parallel_min, len(symbols), '\n'.join(symbols)).encode('utf-8')
    err = ctypes.create_string_buffer(512)
    stats_buf = ctypes.create_string_buffer(8192)
    rc = lib.vcdidx_abi_build(manifest, len(manifest), str(path).encode('utf-8'),
                              str(sidecar).encode('utf-8'), err, 512,
                              stats_buf, 8192)
    if rc != 0:
        raise ValueError(err.value.decode('utf-8', 'replace')
                         or 'native builder failed')
    stats = json.loads(stats_buf.value.decode('utf-8'))
    stats['build_s'] = time.perf_counter() - started
    stats['data_start'] = start
    stats['directory_bytes'] = (56 + 32 * stats['blocks']
                                + 16 * stats['raw_symbols'])
    return stats
# ================================================================
# Part 9: CLI entry
# ================================================================



def _add_time_args(sp):
    sp.add_argument('--begin', metavar='TIME',
                    help='start time, e.g. 0, 100ns, 17.5us (omit = from start)')
    sp.add_argument('--end', metavar='TIME',
                    help='end time, same format (omit = no upper bound)')


def _add_filter(sp):
    sp.add_argument('--filter', metavar='K1,K2,...',
                    type=_normalize_filter_patterns,
                    help='comma-separated patterns, case-insensitive: an exact full path selects '
                         'that signal only, other text matches as a substring, * and ? glob')


def _add_output(sp):
    sp.add_argument('-o', '--output', dest='output_file', metavar='FILE', default=None,
                    help='write the result to FILE instead of stdout (stdout gets a one-line '
                         'receipt); use it to keep a --limit 0 result. On a terminal, stdout '
                         'output stops after 1 MiB')


def _add_common(sp):
    # Also accept global-style output controls after the subcommand.
    # Defaults are SUPPRESS so values supplied before the subcommand survive.
    sp.add_argument('--json', action='store_true', default=argparse.SUPPRESS,
                    help='output compact structured JSON instead of text')
    sp.add_argument('--limit', type=int, default=argparse.SUPPRESS,
                    help='max rows/records to emit; default 500; 0 = unlimited; streaming commands stop after the first unshown result')
    sp.add_argument('--verbose', action='store_true', default=argparse.SUPPRESS,
                    help='show extra fields; if --limit is omitted, disables truncation')


def main():
    global _AUTO_SCRIPT_PATH
    _AUTO_SCRIPT_PATH = os.path.abspath(sys.argv[0])
    p = argparse.ArgumentParser(
        prog='vcd_analyzer',
        description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument('--json', action='store_true',
                   help='output compact structured JSON instead of text')
    p.add_argument('--limit', type=int, default=None,
                   help='max rows/records to emit; default 500; 0 = unlimited; streaming commands stop after the first unshown result')
    p.add_argument('--verbose', action='store_true',
                   help='show extra fields; if --limit is omitted, disables truncation')
    p.add_argument('--version', action='version', version='%(prog)s ' + __version__)
    sub = p.add_subparsers(dest='cmd', metavar='<command>')

    sp = sub.add_parser('index', help='build the optional .vcidx sidecar for fast random access')
    sp.add_argument('file', metavar='<file>')
    sp.add_argument('--block-mib', type=int, default=None, metavar='N',
                    help='index block size in MiB, 1..4096 (default: automatic — '
                         '1 MiB, doubled while the index would exceed 2%% of the file)')
    sp.add_argument('--force', action='store_true',
                    help='rebuild even if the sidecar already exists')
    sp.add_argument('--output', metavar='PATH', default=None,
                    help='write the sidecar at PATH (must end with .vcidx) and link <file>.vcidx to it')
    sp.add_argument('--threads', type=int, default=None, metavar='N',
                    help='native builder threads, 1..16 (default min(4, cores))')
    sp.add_argument('--auto', action='store_true', help=argparse.SUPPRESS)
    _add_common(sp)

    sp = sub.add_parser('info', help='file overview: timescale, signal count, time span, scopes')
    sp.add_argument('file', metavar='<file>', help='VCD file path'); _add_common(sp); _add_output(sp)

    sp = sub.add_parser('list', help='list signals with path and bit width')
    sp.add_argument('file', metavar='<file>'); _add_filter(sp); _add_common(sp); _add_output(sp)

    sp = sub.add_parser('dump', help='print value-change events in time order')
    sp.add_argument('file', metavar='<file>'); _add_time_args(sp); _add_filter(sp); _add_common(sp)
    _add_output(sp)

    sp = sub.add_parser('summary', help='window stats: active/static/undefined selected signals')
    sp.add_argument('file', metavar='<file>'); _add_time_args(sp); _add_filter(sp); _add_common(sp)
    _add_output(sp)

    sp = sub.add_parser('snapshot', help='known signal values at a given time point')
    sp.add_argument('file', metavar='<file>')
    sp.add_argument('--at', metavar='TIME', required=True, help='time point, e.g. 17.55us')
    _add_filter(sp); _add_common(sp); _add_output(sp)

    sp = sub.add_parser('compare', help='diff known signal values between two time points')
    sp.add_argument('file', metavar='<file>')
    sp.add_argument('--at', metavar='T1,T2', required=True, help='two time points comma-separated, e.g. 17.5us,17.7us')
    _add_filter(sp); _add_common(sp); _add_output(sp)

    sp = sub.add_parser('search', help='conditional search and associated signal observation')
    sp.add_argument('file', metavar='<file>'); _add_time_args(sp); _add_common(sp); _add_output(sp)
    sp.add_argument('--condition', metavar='COND', required=True, action='append',
                    help='comma-separated AND terms: SIG=VAL, SIG!=VAL, or changed(SIG); '
                         '!= does not match x/z/undef. Repeat the flag to OR the clauses '
                         '(there is no in-string OR). A changed(SIG) term switches to event '
                         'mode; then every clause must carry one')
    sp.add_argument('--show', metavar='PAT1,PAT2,...', type=_normalize_filter_patterns,
                    help='signals to display while the condition holds; output segments split when shown values change')
    sp.add_argument('--changed', metavar='PATTERN', default=None,
                    help=argparse.SUPPRESS)

    args = p.parse_args()
    if not args.cmd:
        p.print_help()
        sys.exit(_EXIT_ERROR)
    try:
        status = _main(args)
    except FileNotFoundError as e:
        status = _error('cannot open VCD file: {}'.format(e.filename or args.file))
    except IsADirectoryError as e:
        status = _error('not a file: {}'.format(e.filename or args.file))
    except PermissionError as e:
        status = _error('permission denied: {}'.format(e.filename or args.file))
    except BrokenPipeError:
        raise
    except (OSError, _UserError) as e:
        status = _error(str(e))
    if status:
        sys.exit(status)


def _error(message):
    try:
        sys.stderr.write('Error: {}\n'.format(message))
    except (OSError, ValueError):
        pass
    return _EXIT_ERROR


def _main(args):
    """Run the parsed command; returns its exit status (None = 0)."""
    _variant_env_notice()
    block_mib = getattr(args, 'block_mib', None)
    if block_mib is not None and not 1 <= block_mib <= 4096:
        raise _UserError('--block-mib must be between 1 and 4096')
    threads = getattr(args, 'threads', None)
    if threads is not None and not 1 <= threads <= 16:
        raise _UserError('--threads must be between 1 and 16')
    if getattr(args, 'changed', None) is not None:
        # Removed in 1.5.0: the flag's event mode was a variant of --condition
        # wearing a flag's clothes, and being a flag it applied to the whole
        # query — an edge could not be scoped to one OR clause, and two signals
        # could not be required to transition together.
        raise _UserError('--changed was removed; write the edge as a condition term instead: '
                         '--condition "changed({})"'.format(args.changed))

    cmds = {'info': cmd_info, 'list': cmd_list, 'dump': cmd_dump, 'summary': cmd_summary,
            'snapshot': cmd_snapshot, 'compare': cmd_compare, 'search': cmd_search}
    # The index accelerates only the change-stream commands; info,
    # list and index itself run on the plain parser (no sidecar mmap,
    # no auto-build judgment on their behalf).
    stream_cmd = args.cmd in ('dump', 'summary', 'snapshot', 'compare', 'search')
    vcd = (try_index(args.file) or VCDParser(args.file)) if stream_cmd \
        else VCDParser(args.file)
    if stream_cmd:
        maybe_auto_build(vcd, args.file)
    try:
        if vcd.timescale_warning:
            try:
                sys.stderr.write('Warning: {}\n'.format(vcd.timescale_warning))
            except (OSError, ValueError):
                pass
        if args.cmd == 'index':
            return cmd_index(vcd, args)
        return _run_command(cmds[args.cmd], vcd, args)
    finally:
        close = getattr(vcd, 'close', None)
        if close is not None:
            close()


if __name__ == '__main__':
    import signal as _sig
    if hasattr(_sig, 'SIGPIPE'):
        _sig.signal(_sig.SIGPIPE, _sig.SIG_DFL)
    # Verbatim VCD text and ensure_ascii=False JSON can carry non-ASCII
    # characters (signal paths, $version/$date strings). Force UTF-8 so a
    # legacy Windows codepage cannot turn a valid dump into a
    # UnicodeEncodeError. No-op where reconfigure() is unavailable.
    for _stream in (sys.stdout, sys.stderr):
        try:
            _stream.reconfigure(encoding='utf-8', errors='replace')
        except (AttributeError, ValueError, OSError):
            pass
    try:
        main()
    except KeyboardInterrupt:
        # Conventional 128 + SIGINT(2): a clean exit, no traceback.
        sys.exit(130)
    except BrokenPipeError:
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except Exception:
            pass
        sys.exit(0)
